CREATE OR REPLACE FUNCTION public.finance_tax_source(t uuid,d date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s finance_schedule_settings;fy date;profit numeric;prior numeric;target numeric;stamp text;BEGIN IF NOT public.user_has_tenant(auth.uid(),t) THEN RAISE EXCEPTION 'Tenant access required';END IF;SELECT * INTO s FROM finance_schedule_settings WHERE tenant_id=t;IF NOT FOUND OR NOT s.tax_enabled THEN RAISE EXCEPTION 'Tax setup is not enabled';END IF;
fy:=make_date(extract(year FROM d)::int,s.year_end_month,least(s.year_end_day,extract(day FROM(make_date(extract(year FROM d)::int,s.year_end_month,1)+interval '1 month -1 day'))::int))+1;IF fy>d THEN fy:=(fy-interval '1 year')::date;END IF;
SELECT greatest(coalesce(sum(l.credit-l.debit),0),0),md5(coalesce(string_agg(e.id::text||':'||l.id::text||':'||l.account_id::text||':'||l.debit||':'||l.credit,',' ORDER BY e.id,l.id),'')) INTO profit,stamp FROM journal_lines l JOIN journal_entries e ON e.id=l.entry_id JOIN chart_of_accounts c ON c.id=l.account_id WHERE e.tenant_id=t AND e.status='posted' AND e.entry_date BETWEEN fy AND d AND c.account_type IN('revenue','other_income','cogs','opex','other_expense') AND c.code<>'6950';
SELECT coalesce(sum(l.debit-l.credit),0) INTO prior FROM journal_lines l JOIN journal_entries e ON e.id=l.entry_id JOIN chart_of_accounts c ON c.id=l.account_id WHERE e.tenant_id=t AND e.status='posted' AND e.entry_date BETWEEN fy AND d AND c.code='6950';target:=round(least(profit,2000000)*CASE WHEN s.business_type='company' THEN .0825 ELSE .075 END+greatest(profit-2000000,0)*CASE WHEN s.business_type='company' THEN .165 ELSE .15 END,2);
RETURN jsonb_build_object('fy',fy,'through',d,'profit',profit,'target',target,'prior',prior,'amount',target-prior,'ledger',stamp,'settings',md5(to_jsonb(s)::text));END $$;
REVOKE ALL ON FUNCTION public.finance_tax_source(uuid,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_tax_source(uuid,date) TO authenticated;
DO $$ DECLARE def text;BEGIN
SELECT pg_get_functiondef('public.finance_schedule_prepare(uuid,date)'::regprocedure) INTO def;def:=replace(def,'jsonb_build_object(''profit'',profit,''target_tax'',setaside)','jsonb_build_object(''profit'',profit,''target_tax'',setaside,''tax_source'',finance_tax_source(t,ending))');IF def NOT LIKE '%tax_source%' THEN RAISE EXCEPTION 'Tax preparation integration unavailable';END IF;EXECUTE def;
SELECT pg_get_functiondef('public.finance_schedule_approve(uuid,uuid,date)'::regprocedure) INTO def;def:=replace(def,'IF q.kind=''tax'' THEN RAISE EXCEPTION ''Tax source revalidation not yet available; approval blocked'';END IF;','IF q.kind=''tax'' THEN IF NOT(q.source_data ? ''tax_source'') OR finance_tax_source(t,q.entry_date) IS DISTINCT FROM q.source_data->''tax_source'' THEN RAISE EXCEPTION ''Tax source changed; cancel and prepare again'';END IF;IF jsonb_array_length(q.lines)<>2 OR NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE tenant_id=t AND code=''6950'' AND id=(q.lines->0->>''account_id'')::uuid) OR NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE tenant_id=t AND code=''2350'' AND id=(q.lines->1->>''account_id'')::uuid) OR abs((q.lines->0->>''debit'')::numeric-(q.lines->0->>''credit'')::numeric-((q.source_data->''tax_source'')->>''amount'')::numeric)>.005 THEN RAISE EXCEPTION ''Tax draft no longer matches source'';END IF;END IF;');
-- Lock before any deferred source/balance reads to serialize all selected approvals.
def:=replace(def,'PERFORM finance_assert_open(t,q.entry_date);','PERFORM finance_assert_open(t,q.entry_date);PERFORM pg_advisory_xact_lock(hashtextextended(''schedule:''||t::text,0));');
def:=replace(def,'IF i.status<>''active'' OR i.used_amount','IF i.id IS NULL OR i.status<>''active'' OR i.used_amount');
def:=replace(def,'FOR l IN SELECT * FROM jsonb_array_elements(q.source_data->''uses'') LOOP SELECT','FOR l IN SELECT * FROM jsonb_array_elements(q.source_data->''sold_items'') LOOP IF NOT EXISTS(SELECT 1 FROM finance_deferred_items WHERE tenant_id=t AND id=(l#>>''{}'')::uuid AND status=''draft'' AND source_sales_id=(q.source_data->>''sales_id'')::uuid) THEN RAISE EXCEPTION ''Deferred issued item changed'';END IF;END LOOP;FOR l IN SELECT * FROM jsonb_array_elements(q.source_data->''uses'') LOOP SELECT');
IF def LIKE '%Tax source revalidation not yet available%' THEN RAISE EXCEPTION 'Tax approval patch failed';END IF;EXECUTE def;
SELECT pg_get_functiondef('public.finance_sales_deferred_save(uuid,jsonb)'::regprocedure) INTO def;def:=replace(def,'INSERT INTO sales_records(id,tenant_id','PERFORM set_config(''finance.deferred_insert'',rid::text,true);INSERT INTO sales_records(id,tenant_id');EXECUTE def;
SELECT pg_get_functiondef('public.finance_deferred_sales_guard()'::regprocedure) INTO def;def:=replace(def,'BEGIN IF TG_OP=''UPDATE''','BEGIN IF TG_OP=''INSERT'' AND NEW.deferred_feed AND (current_setting(''finance.deferred_insert'',true) IS DISTINCT FROM NEW.id::text) THEN RAISE EXCEPTION ''Use the guarded deferred draft flow'';END IF;IF TG_OP=''UPDATE''');EXECUTE def;
END $$;
CREATE OR REPLACE FUNCTION public.finance_receipt_deferred_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='posted' AND coalesce((NEW.tentative_values->>'vouchersSold')::numeric,0)+coalesce((NEW.tentative_values->>'depositsTaken')::numeric,0)+coalesce((NEW.tentative_values->>'vouchersUsed')::numeric,0)+coalesce((NEW.tentative_values->>'depositsUsed')::numeric,0)>0 THEN RAISE EXCEPTION 'Deferred receipt requires confirmed draft flow';END IF;RETURN NEW;END $$;
CREATE TRIGGER receipt_deferred_guard BEFORE UPDATE ON public.sales_receipt_intakes FOR EACH ROW EXECUTE FUNCTION public.finance_receipt_deferred_guard();